// Handshake de verificação do webhook da Meta (App Dashboard → WhatsApp →
// Configuração → Webhook). META_VERIFY_TOKEN é uma senha que você escolhe e
// configura em duas pontas: aqui (variável de ambiente do n8n) e no painel
// da Meta, no mesmo campo "Verify token".
const query = $input.item.json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
const esperado = $env.META_VERIFY_TOKEN;

const valido = mode === 'subscribe' && !!esperado && token === esperado;
return { valido, challenge: valido ? challenge : '' };

// v4/Meta — resolvido pelo node "Postgres — Resolver tenant" a partir do
// phone_number_id. Mantém os nomes de campo remoteJid/instanceName do fluxo
// Evolution (agora: phone digits / phone_number_id) pra não precisar tocar
// nos nodes de lógica de menu/agendamento adiante.
const TENANT_ID = $input.item.json.tenant_id;

const body = $('Webhook — Meta (mensagens)').first().json.body;
const value = body.entry[0].changes[0].value;
const msg = value.messages[0];

const phone = msg.from; // já vem em formato internacional (ex: "5534998887777"), sem "+"
const message = ((msg.text && msg.text.body) || '').trim();
const pushName = (value.contacts && value.contacts[0] && value.contacts[0].profile && value.contacts[0].profile.name) || 'cliente';
const phoneNumberId = value.metadata.phone_number_id;

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessionKey = 'session_' + phone;
let session = staticData.sessions[sessionKey] || { step: 'menu', data: {} };

if (message === '0') {
  session = { step: 'menu', data: {} };
}

return {
  tenantId: TENANT_ID,
  phone,
  remoteJid: phone,
  message,
  pushName,
  instanceName: phoneNumberId,
  step: session.step,
  sessionData: session.data || {},
};

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;

const responseText = 'Olá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vinda ao Salão Kyvvo!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento';

staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };

return { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText };

const item = $input.item.json;
const msg = item.message;
let acao = 'invalido';
if (msg === '1') acao = 'agendar';
else if (msg === '2') acao = 'reagendar';
else if (msg === '3') acao = 'cancelar';

return Object.assign({}, item, { acao });

const ctx = $('Menu opção — decidir').first().json;
const rows = $input.all().map(i => i.json);
// tenants.onboarding_horario_revisado só vira true quando o admin confirma
// o horário de funcionamento ao menos uma vez (Configuração no painel) — sem
// isso, o cálculo de horários disponíveis roda em cima de um valor padrão
// que pode não bater com o funcionamento real do salão.
const horarioRevisado = $('Postgres — Resolver tenant').first().json.onboarding_horario_revisado;

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

let responseText;
if (rows.length === 0 || !horarioRevisado) {
  responseText = 'Estamos finalizando os últimos ajustes por aqui! 🛠️\n\nEm breve vamos te atender com muito carinho — tente novamente mais tarde.\n\n_Digite 0 para voltar ao menu._';
  staticData.sessions[sessionKey] = { step: 'menu', data: {} };
} else {
  const linhas = rows.map((s, idx) => (idx + 1) + '️⃣ ' + s.nome + ' — ' + s.duracao_minutos + 'min — R$ ' + Number(s.preco).toFixed(2));
  responseText = 'Ótimo! Qual serviço você deseja? 💇\n\n' + linhas.join('\n');
  staticData.sessions[sessionKey] = { step: 'escolher_servico', data: { servicosDisponiveis: rows } };
}

return { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText };

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;
let responseText;
let nextStep;
let nextData = {};

if (item.acao === 'reagendar') {
  responseText = 'Entendido! ✅ Nossa equipe vai entrar em contato para confirmar o novo horário.\n\n_Digite 0 para voltar ao menu._';
  nextStep = 'menu';
} else if (item.acao === 'cancelar') {
  responseText = 'Cancelamento registrado. ✅\n\nSe precisar reagendar, é só nos chamar! 💜\n\n_Digite 0 para voltar ao menu._';
  nextStep = 'menu';
} else {
  // Depois de 3 tentativas inválidas seguidas na mesma etapa, reinicia o
  // fluxo do zero em vez de repetir a mesma pergunta pra sempre.
  const tentativas = ((item.sessionData && item.sessionData.tentativasInvalidas) || 0) + 1;
  if (tentativas >= 3) {
    responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vinda ao Salão Kyvvo!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento';
    nextStep = 'menu_opcao';
    nextData = {};
  } else {
    responseText = 'Opção inválida. Por favor, escolha:\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento';
    nextStep = 'menu_opcao';
    nextData = { tentativasInvalidas: tentativas };
  }
}

staticData.sessions[sessionKey] = { step: nextStep, data: nextData };

return { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText };

const item = $input.item.json;
const servicos = (item.sessionData && item.sessionData.servicosDisponiveis) || [];
const idx = parseInt(item.message, 10) - 1;
const valido = Number.isInteger(idx) && idx >= 0 && idx < servicos.length;

return Object.assign({}, item, { valido, servicoEscolhido: valido ? servicos[idx] : null });

const ctx = $('Validar serviço escolhido').first().json;
const rows = $input.all().map(i => i.json);

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

let responseText;
if (rows.length === 0) {
  responseText = 'No momento não temos profissionais disponíveis para esse serviço. 😔\n\n_Digite 0 para voltar ao menu._';
  staticData.sessions[sessionKey] = { step: 'menu', data: {} };
} else {
  const linhas = rows.map((p, idx) => (idx + 1) + '️⃣ ' + p.nome);
  responseText = 'Com quem você prefere? 💜\n\n' + linhas.join('\n');
  staticData.sessions[sessionKey] = { step: 'escolher_profissional', data: { servico: ctx.servicoEscolhido, profissionaisDisponiveis: rows } };
}

return { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText };

