const item = $input.item.json;
const profissionais = (item.sessionData && item.sessionData.profissionaisDisponiveis) || [];
const idx = parseInt(item.message, 10) - 1;
const valido = Number.isInteger(idx) && idx >= 0 && idx < profissionais.length;

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;

let responseText;
if (valido) {
  const profissional = profissionais[idx];
  responseText = 'Qual data você prefere? 📅\n\nResponda no formato DD/MM\nEx: 25/06';
