  const tentativas = ((item.sessionData && item.sessionData.tentativasInvalidas) || 0) + 1;
  if (tentativas >= 3) {
    responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vinda ao Salão Kyvvo!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento';
    staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };
  } else {
    const linhas = profissionais.map((p, i) => (i + 1) + '️⃣ ' + p.nome);
    responseText = 'Opção inválida. Escolha um número da lista:\n\n' + linhas.join('\n');
    staticData.sessions[sessionKey] = { step: 'escolher_profissional', data: Object.assign({}, item.sessionData, { tentativasInvalidas: tentativas }) };
  }
}

return { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText };

const item = $input.item.json;
const dateRegex = /^(0?[1-9]|[12][0-9]|3[01])\/(0?[1-9]|1[0-2])$/;
const msg = item.message;
let valido = false;
let isoDate = null;
let displayDate = msg;

if (dateRegex.test(msg)) {
  const partes = msg.split('/').map(Number);
  const dia = partes[0];
  const mes = partes[1];
  const hoje = new Date();
  let ano = hoje.getFullYear();
  let candidata = new Date(ano, mes - 1, dia);
  const hojeSemHora = new Date(hoje.getFullYear(), hoje.getMonth(), hoje.getDate());
  if (candidata < hojeSemHora) {
    ano += 1;
    candidata = new Date(ano, mes - 1, dia);
  }
  if (candidata.getMonth() === mes - 1 && candidata.getDate() === dia) {
    valido = true;
    isoDate = ano + '-' + String(mes).padStart(2, '0') + '-' + String(dia).padStart(2, '0');
    displayDate = String(dia).padStart(2, '0') + '/' + String(mes).padStart(2, '0');
  }
}

return Object.assign({}, item, { valido, isoDate, displayDate });

const ctx = $('Validar data').first().json;
const ocupados = $input.all().map(i => i.json);

const duracaoServico = ctx.sessionData.servico.duracao_minutos;

// US12 — horário de funcionamento configurável por tenant (antes era uma
// lista fixa 09h-17h hardcoded). Gera slots de hora em hora entre abertura e
// fechamento, pulando o intervalo de almoço 12h-14h (mantido fixo — o modelo
// de configuração hoje só tem abertura/fechamento, sem campo de almoço).
const horarioTenant = $('Postgres — Horário do tenant').first().json;
function paraHHMM(pgTime) {
  return pgTime.slice(0, 5);
}
const aberturaHHMM = paraHHMM(horarioTenant.horario_abertura);
const fechamentoHHMM = paraHHMM(horarioTenant.horario_fechamento);
const ALMOCO_INICIO = '12:00';
const ALMOCO_FIM = '14:00';

function paraMinutosLocal(hhmm) {
  const partes = hhmm.split(':').map(Number);
  return partes[0] * 60 + partes[1];
}

const aberturaMin = paraMinutosLocal(aberturaHHMM);
const fechamentoMin = paraMinutosLocal(fechamentoHHMM);
const almocoInicioMin = paraMinutosLocal(ALMOCO_INICIO);
const almocoFimMin = paraMinutosLocal(ALMOCO_FIM);

const HORARIOS_BASE = [];
for (let m = aberturaMin; m < fechamentoMin; m += 60) {
  if (m >= almocoInicioMin && m < almocoFimMin) continue;
  const h = String(Math.floor(m / 60)).padStart(2, '0');
  const min = String(m % 60).padStart(2, '0');
  HORARIOS_BASE.push(h + ':' + min);
}

function paraMinutos(hhmm) {
  const partes = hhmm.split(':').map(Number);
  return partes[0] * 60 + partes[1];
}

const OFFSET_SP_MINUTOS = 180; // America/Sao_Paulo = UTC-3 (sem horário de verão desde 2019)
const intervalosOcupados = ocupados.map(o => {
  const inicio = new Date(o.data_hora);
  const inicioMinUtc = inicio.getUTCHours() * 60 + inicio.getUTCMinutes();
  const inicioMin = inicioMinUtc - OFFSET_SP_MINUTOS;
  return { inicio: inicioMin, fim: inicioMin + o.duracao_minutos };
});

const disponiveis = HORARIOS_BASE.filter(h => {
  const inicio = paraMinutos(h);
  const fim = inicio + duracaoServico;
  if (fim > fechamentoMin) return false;
  return !intervalosOcupados.some(o => inicio < o.fim && fim > o.inicio);
});

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

let responseText;
if (disponiveis.length === 0) {
  responseText = 'Não há horários disponíveis em ' + ctx.displayDate + ' para ' + ctx.sessionData.profissional.nome + '. 😔\n\nTente outra data (DD/MM) ou digite 0 para voltar ao menu.';
  staticData.sessions[sessionKey] = { step: 'escolher_data', data: ctx.sessionData };
} else {
  responseText = 'Horários disponíveis em ' + ctx.displayDate + ': ⏰\n\n' + disponiveis.join(' • ');
  staticData.sessions[sessionKey] = { step: 'escolher_horario', data: Object.assign({}, ctx.sessionData, { data: ctx.isoDate, dataDisplay: ctx.displayDate, horariosDisponiveis: disponiveis }) };
}

return { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText };

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;

// Depois de 3 tentativas inválidas seguidas na mesma etapa, reinicia o
// fluxo do zero em vez de repetir a mesma pergunta pra sempre.
const tentativas = ((item.sessionData && item.sessionData.tentativasInvalidas) || 0) + 1;
let responseText;
if (tentativas >= 3) {
  responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vinda ao Salão Kyvvo!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento';
  staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };
} else {
  responseText = 'Data inválida. Por favor, use o formato DD/MM.\nEx: 25/06';
  staticData.sessions[sessionKey] = { step: 'escolher_data', data: Object.assign({}, item.sessionData, { tentativasInvalidas: tentativas }) };
}

return { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText };

const item = $input.item.json;
const horarios = (item.sessionData && item.sessionData.horariosDisponiveis) || [];

function normalizar(txt) {
  let t = txt.trim().toLowerCase().replace('h', '');
  if (/^\d{1,2}$/.test(t)) return t.padStart(2, '0') + ':00';
  if (/^\d{1,2}:\d{2}$/.test(t)) {
    const partes = t.split(':');
    return partes[0].padStart(2, '0') + ':' + partes[1];
  }
  return null;
}

const horarioNorm = normalizar(item.message);
const valido = !!horarioNorm && horarios.includes(horarioNorm);

return Object.assign({}, item, { valido, horarioEscolhido: horarioNorm });

const ctx = $('Validar horário').first().json;

const staticData = $getWorkflowStaticData('global');
staticData.sessions['session_' + ctx.phone] = { step: 'menu', data: {} };

const responseText = '✅ Agendamento confirmado!

💇 ' + ctx.sessionData.servico.nome + '
👤 ' + ctx.sessionData.profissional.nome + '
📅 ' + ctx.sessionData.dataDisplay + ' às ' + ctx.horarioEscolhido + '

Até lá! 💜

_Digite 0 para voltar ao menu._';

return { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText };

